/**
 * Calculate late fee for an invoice.
 * 0.04% of the amount still due for every day the invoice is overdue.
 * Returns 0 if the invoice is not overdue.
 * @param {Object} invoice - Invoice object with dueDate and lines
 * @param {string} asOf - Reference date in YYYY-MM-DD format
 * @returns {number} - Late fee in cents, rounded to nearest cent
 */
export function lateFee(invoice, asOf) {
  if (invoice.dueDate >= asOf) {
    return 0;
  }

  const daysOverdue = daysBetween(invoice.dueDate, asOf);
  const amountDue = balanceDue(invoice);
  const fee = amountDue * daysOverdue * 0.0004;
  return Math.round(fee);
}

